import { pgTable, text, serial, integer, boolean, timestamp, real, varchar } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

export const REPORT_TYPES = ["medical", "lost_self", "lost_other", "volunteer"] as const;
export const REPORT_STATUS = ["active", "resolved", "expired"] as const;

export const reports = pgTable("reports", {
  id: serial("id").primaryKey(),
  type: text("type", { enum: REPORT_TYPES }).notNull(),
  name: text("name"),
  mobile: text("mobile"),
  age: integer("age"),
  gender: text("gender"),
  description: text("description"), // For "Last seen note" or general details
  photoUrl: text("photo_url"),
  lat: real("lat").notNull(),
  lng: real("lng").notNull(),
  status: text("status", { enum: REPORT_STATUS }).default("active").notNull(),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  lastSeenAt: timestamp("last_seen_at").defaultNow().notNull(),
});

export const insertReportSchema = createInsertSchema(reports).omit({ 
  id: true, 
  createdAt: true,
  lastSeenAt: true,
  status: true 
}).extend({
  lat: z.number(),
  lng: z.number(),
  age: z.coerce.number().optional(),
});

export type Report = typeof reports.$inferSelect;
export type InsertReport = z.infer<typeof insertReportSchema>;

export type CreateReportRequest = InsertReport;
export type UpdateReportRequest = Partial<InsertReport> & { status?: typeof REPORT_STATUS[number] };

export const users = pgTable("users", {
  id: serial("id").primaryKey(),
  username: text("username").notNull().unique(),
  password: text("password").notNull(),
  role: text("role").default("volunteer").notNull(),
});

export const insertUserSchema = createInsertSchema(users).omit({ id: true });
export type User = typeof users.$inferSelect;
export type InsertUser = z.infer<typeof insertUserSchema>;

import { z } from 'zod';
import { insertReportSchema, reports, users, insertUserSchema } from './schema';

export const errorSchemas = {
  validation: z.object({
    message: z.string(),
    field: z.string().optional(),
  }),
  notFound: z.object({
    message: z.string(),
  }),
  internal: z.object({
    message: z.string(),
  }),
  unauthorized: z.object({
    message: z.string(),
  }),
};

export const api = {
  reports: {
    create: {
      method: 'POST' as const,
      path: '/api/reports',
      input: insertReportSchema,
      responses: {
        201: z.custom<typeof reports.$inferSelect>(),
        400: errorSchemas.validation,
      },
    },
    list: {
      method: 'GET' as const,
      path: '/api/reports',
      input: z.object({
        status: z.enum(["active", "resolved", "expired"]).optional(),
        type: z.string().optional(),
      }).optional(),
      responses: {
        200: z.array(z.custom<typeof reports.$inferSelect>()),
      },
    },
    get: {
      method: 'GET' as const,
      path: '/api/reports/:id',
      responses: {
        200: z.custom<typeof reports.$inferSelect>(),
        404: errorSchemas.notFound,
      },
    },
    update: {
      method: 'PATCH' as const,
      path: '/api/reports/:id',
      input: insertReportSchema.partial().extend({
        status: z.enum(["active", "resolved", "expired"]).optional()
      }),
      responses: {
        200: z.custom<typeof reports.$inferSelect>(),
        404: errorSchemas.notFound,
      },
    },
  },
  auth: {
    login: {
      method: 'POST' as const,
      path: '/api/auth/login',
      input: z.object({
        username: z.string(),
        password: z.string(),
      }),
      responses: {
        200: z.custom<typeof users.$inferSelect>(),
        401: errorSchemas.unauthorized,
      },
    },
    logout: {
